To compute the n-th Fibonacci number modulo `p` efficiently, you can use matrix exponentiation. This method allows you to compute the Fibonacci number in \(O(\log n)\) time, which is much more efficient than the naive recursive approach.

Here's a JavaScript function that computes the n-th Fibonacci number modulo `p` using matrix exponentiation:

```javascript
function matrixMultiply(A, B, p) {
    return [
        [(A[0][0] * B[0][0] + A[0][1] * B[1][0]) % p, (A[0][0] * B[0][1] + A[0][1] * B[1][1]) % p],
        [(A[1][0] * B[0][0] + A[1][1] * B[1][0]) % p, (A[1][0] * B[0][1] + A[1][1] * B[1][1]) % p]
    ];
}

function matrixPower(matrix, power, p) {
    let result = [[1, 0], [0, 1]]; // Identity matrix
    let base = matrix;

    while (power > 0) {
        if (power % 2 === 1) {
            result = matrixMultiply(result, base, p);
        }
        base = matrixMultiply(base, base, p);
        power = Math.floor(power / 2);
    }

    return result;
}

function fibonacciMod(n, p) {
    if (n === 0) return 0;
    if (n === 1) return 1;

    const F = [[1, 1], [1, 0]];
    const resultMatrix = matrixPower(F, n - 1, p);

    return resultMatrix[0][0];
}

// Example usage:
const n = 10;
const p = 1000000007;
console.log(fibonacciMod(n, p)); // Outputs the 10th Fibonacci number modulo 1000000007
```

### Explanation:
1. **Matrix Multiplication**: The `matrixMultiply` function multiplies two 2x2 matrices and takes the result modulo `p`.
2. **Matrix Exponentiation**: The `matrixPower` function raises a matrix to a given power using exponentiation by squaring. This is efficient and avoids redundant computations.
3. **Fibonacci Calculation**: The `fibonacciMod` function uses the matrix exponentiation to compute the n-th Fibonacci number modulo `p`. The transformation matrix for Fibonacci numbers is `[[1, 1], [1, 0]]`, and raising this matrix to the power of `n-1` gives the n-th Fibonacci number.

This approach ensures that the computation is efficient even for large values of `n`.

Creating a blockchain that rewards node owners for hosting data and handles data storage deposits, lifetime extension, and data retrieval fees is a complex task. Below is a simplified version of such a system using Python. This example will focus on the key functionalities: data deposit, lifetime extension, data retrieval fees, and data deletion with deposit refunds.

```python
import hashlib
import json
import time
from typing import List, Dict

class Block:
    def __init__(self, index: int, previous_hash: str, timestamp: float, data: Dict, nonce: int = 0, hash: str = None):
        self.index = index
        self.previous_hash = previous_hash
        self.timestamp = timestamp
        self.data = data
        self.nonce = nonce
        self.hash = hash or self.calculate_hash()

    def calculate_hash(self) -> str:
        block_string = json.dumps(self.__dict__, sort_keys=True)
        return hashlib.sha256(block_string.encode()).hexdigest()

class Blockchain:
    def __init__(self):
        self.chain: List[Block] = [self.create_genesis_block()]
        self.nodes = {}
        self.data_storage_deposits = {}

    def create_genesis_block(self) -> Block:
        return Block(index=0, previous_hash='0', timestamp=time.time(), data={})

    def get_latest_block(self) -> Block:
        return self.chain[-1]

    def add_block(self, new_block: Block) -> None:
        new_block.previous_hash = self.get_latest_block().hash
        new_block.hash = new_block.calculate_hash()
        self.chain.append(new_block)

    def add_data(self, data: Dict, data_size: int, data_lifetime: int, depositor: str, deposit_amount: float) -> None:
        new_block = Block(index=self.get_latest_block().index + 1,
                          previous_hash=self.get_latest_block().hash,
                          timestamp=time.time(),
                          data={'data': data, 'size': data_size, 'lifetime': data_lifetime, 'depositor': depositor, 'deposit_amount': deposit_amount})
        self.add_block(new_block)
        self.data_storage_deposits[new_block.hash] = {'deposit_amount': deposit_amount, 'lifetime': data_lifetime, 'nodes': {}}

    def extend_data_lifetime(self, data_hash: str, additional_lifetime: int, additional_deposit: float) -> None:
        if data_hash in self.data_storage_deposits:
            self.data_storage_deposits[data_hash]['lifetime'] += additional_lifetime
            self.data_storage_deposits[data_hash]['deposit_amount'] += additional_deposit

    def delete_data(self, data_hash: str, depositor: str) -> None:
        if data_hash in self.data_storage_deposits and self.data_storage_deposits[data_hash]['depositor'] == depositor:
            deposit_refund = self.data_storage_deposits[data_hash]['deposit_amount']
            del self.data_storage_deposits[data_hash]
            return deposit_refund
        return 0

    def access_data(self, data_hash: str, node: str) -> Dict:
        if data_hash in self.data_storage_deposits:
            data = self.chain[self.get_block_index_by_hash(data_hash)].data['data']
            self.nodes[node] = self.nodes.get(node, 0) + 1  # Increment node access count
            return data
        return {}

    def get_block_index_by_hash(self, data_hash: str) -> int:
        for index, block in enumerate(self.chain):
            if block.hash == data_hash:
                return index
        return -1

    def reward_nodes(self) -> None:
        current_time = time.time()
        for data_hash, deposit_info in self.data_storage_deposits.items():
            if current_time - self.get_block_by_hash(data_hash).timestamp > deposit_info['lifetime']:
                reward_amount = deposit_info['deposit_amount'] / len(deposit_info['nodes'])
                for node in deposit_info['nodes']:
                    self.nodes[node] += reward_amount  # Distribute reward to nodes
                del self.data_storage_deposits[data_hash]

    def get_block_by_hash(self, data_hash: str) -> Block:
        for block in self.chain:
            if block.hash == data_hash:
                return block
        return None

# Example usage:
blockchain = Blockchain()

# Add data to blockchain
blockchain.add_data({'key': 'value'}, 1024, 3600, 'node1', 10.0)
blockchain.add_data({'key': 'another_value'}, 2048, 7200, 'node2', 20.0)

# Extend data lifetime
blockchain.extend_data_lifetime(blockchain.chain[1].hash, 3600, 5.0)

# Access data
data = blockchain.access_data(blockchain.chain[1].hash, 'node3')

# Delete data
refund = blockchain.delete_data(blockchain.chain[1].hash, 'node1')

# Reward nodes
blockchain.reward_nodes()
```

### Explanation:
1. **Block Class**: Represents a block in the blockchain.
2. **Blockchain Class**: Manages the blockchain, including adding blocks, adding data, extending data lifetime, deleting data, accessing data, and rewarding nodes.
3. **add_data**: Adds data to the blockchain and records the deposit.
4. **extend_data_lifetime**: Extends the lifetime of data and increases the deposit.
5. **delete_data**: Deletes data and refunds the unused deposit.
6. **access_data**: Allows nodes to access data and increments the access count.
7. **reward_nodes**: Distributes rewards to nodes that have stored data for the specified lifetime.

