In HighFive, a C++ library for reading and writing HDF5 files, you can create compound datatypes to represent complex structures like the `Data` struct you provided. Compound datatypes allow you to group different types of data into a single structure.

Below is an example of how to create a compound datatype for the `Data` struct and use it with HighFive:

1. **Include the necessary headers**:
   ```cpp
   #include <h5xx/predicates.hpp>
   #include <h5xx/attributes.hpp>
   #include <h5xx/group.hpp>
   #include <h5xx/dataset.hpp>
   #include <h5xx/datatype.hpp>
   #include <h5xx/hdf5.hpp>
   #include <vector>
   ```

2. **Define the `Data` struct**:
   ```cpp
   struct Data {
       double v[3];
       int n;
   };
   ```

3. **Create the compound datatype**:
   ```cpp
   h5::DataType compoundDT(h5::DataType::create<H5::CompoundType>(sizeof(Data)));
   compoundDT.insertMember("v", HOFFSET(Data, v), h5::DataType::create<double>());
   compoundDT.insertMember("n", HOFFSET(Data, n), h5::DataType::create<int>());
   ```

4. **Create and write data to an HDF5 file**:
   ```cpp
   int main() {
       h5::File file("example.h5", h5::File::CREATE);

       // Define the compound datatype
       h5::DataType compoundDT(h5::DataType::create<H5::CompoundType>(sizeof(Data)));
       compoundDT.insertMember("v", HOFFSET(Data, v), h5::DataType::create<double>());
       compoundDT.insertMember("n", HOFFSET(Data, n), h5::DataType::create<int>());

       // Create a dataset with the compound datatype
       std::vector<Data> dataVector = {{{1.1, 2.2, 3.3}, 42}, {{4.4, 5.5, 6.6}, 12}};
       h5::DataSet dataset = file.createDataSet("data", compoundDT, {dataVector.size()});

       // Write the data to the dataset
       dataset.write(dataVector.data(), compoundDT, h5::DataSpace{dataVector.size()});

       return 0;
   }
   ```

5. **Include the necessary namespace**:
   ```cpp
   using namespace h5;
   ```

Here is the complete code:

```cpp
#include <h5xx/predicates.hpp>
#include <h5xx/attributes.hpp>
#include <h5xx/group.hpp>
#include <h5xx/dataset.hpp>
#include <h5xx/datatype.hpp>
#include <h5xx/hdf5.hpp>
#include <vector>
#include <iostream>

struct Data {
    double v[3];
    int n;
};

int main() {
    h5::File file("example.h5", h5::File::CREATE);

    // Define the compound datatype
    h5::DataType compoundDT(h5::DataType::create<H5::CompoundType>(sizeof(Data)));
    compoundDT.insertMember("v", HOFFSET(Data, v), h5::DataType::create<double>());
    compoundDT.insertMember("n", HOFFSET(Data, n), h5::DataType::create<int>());

    // Create a dataset with the compound datatype
    std::vector<Data> dataVector = {{{1.1, 2.2, 3.3}, 42}, {{4.4, 5.5, 6.6}, 12}};
    h5::DataSet dataset = file.createDataSet("data", compoundDT, {dataVector.size()});

    // Write the data to the dataset
    dataset.write(dataVector.data(), compoundDT, h5::DataSpace{dataVector.size()});

    return 0;
}
```

