cd substring_match
```

### Step 2: Update `Cargo.toml`

Open `Cargo.toml` and ensure it looks something like this:
```toml
[package]
name = "substring_match"
version = "0.1.0"
edition = "2021"

# See more keys and their definitions at https://doc.rust-lang.org/cargo/reference/manifest.html
[dependencies]
```

### Step 3: Write the Code

Open `src/main.rs` and replace its content with the following code:

```rust
use std::env;
use std::fs::File;
use std::io::{self, BufRead};
use std::path::Path;

fn main() -> io::Result<()> {
    // Parse command-line arguments
    let args: Vec<String> = env::args().collect();
    if args.len() != 3 {
        eprintln!("Usage: {} <substring> <file>", args[0]);
        return Ok(());
    }

    let substring = &args[1];
    let filename = &args[2];

    // Read the file
    if let Ok(lines) = read_lines(filename) {
        for line in lines {
            if let Ok(contents) = line {
                if contents.contains(substring) {
                    println!("{}", contents);
                }
            }
        }
    } else {
        eprintln!("Could not read file: {}", filename);
    }

    Ok(())
}

// The output is wrapped in a Result to allow handling errors
fn read_lines<P>(filename: P) -> io::Result<io::Lines<io::BufReader<File>>>
where
    P: AsRef<Path>,
{
    let file = File::open(filename)?;
    Ok(io::BufReader::new(file).lines())
}
```

### Step 4: Build and Run the Application

Build the project:
```sh
cargo build --release
```

Run the application with a substring and a file:
```sh
cargo run --release <substring> <file>
```

For example:
```sh
cargo run --release "hello" test.txt
```

If `test.txt` contains:
```
hello world
this is a test
hello rust
```

The output will be:
```
hello world
hello rust
```

