import json

class Character:
    def __init__(self, char_data):
        self.name = char_data["name"]
        self.hp = char_data["hp"]
        self.max_hp = char_data["hp"]
        self.damage = char_data["damage"]

class Action:
    def __init__(self, action_data):
        self.action_data = action_data

    def execute(self, actor, target=None):
        action_type = self.action_data["type"]
        if action_type == "deal_damage":
            target.hp -= self.action_data["amount"]
        elif action_type == "heal_actor":
            actor.hp = min(actor.hp + self.action_data["amount"], actor.max_hp)
        elif action_type == "heal_target":
            target.hp = min(target.hp + self.action_data["amount"], target.max_hp)
        elif action_type == "deal_damage_portion_target":
            portion = self.action_data["portion"]
            damage = target.hp * portion
            target.hp -= damage
        elif action_type == "deal_damage_portion_actor":
            portion = self.action_data["portion"]
            damage = actor.hp * portion
            actor.hp -= damage
            target.hp -= damage
        elif action_type == "life_leech":
            damage = self.action_data["amount"]
            target.hp -= damage
            actor.hp = min(actor.hp + damage * self.action_data["leech_portion"], actor.max_hp)
        else:
            raise ValueError(f"Unknown action type: {action_type}")

# Example configuration file (in JSON format)
config = '''
[
    {
        "type": "deal_damage",
        "amount": 10
    },
    {
        "type": "heal_actor",
        "amount": 5
    },
    {
        "type": "heal_target",
        "amount": 5
    },
    {
        "type": "deal_damage_portion_target",
        "portion": 0.2
    },
    {
        "type": "deal_damage_portion_actor",
        "portion": 0.1
    },
    {
        "type": "life_leech",
        "amount": 15,
        "leech_portion": 0.5
    }
]
'''

# Load the configuration
actions_config = json.loads(config)
actions = [Action(action) for action in actions_config]

# Example characters
actor = Character({"name": "Hero", "hp": 100, "damage": 10})
target = Character({"name": "Enemy", "hp": 100, "damage": 5})

