```javascript
function findEntityKey(json, entityKey) {
    function recursiveSearch(obj, key, path) {
        if (obj instanceof Object) {
            for (let k in obj) {
                if (obj.hasOwnProperty(k)) {
                    let newPath = path.slice(); // Clone the current path
                    newPath.push(k);

                    if (k === key) {
                        return { value: obj[k], path: newPath };
                    } else if (obj[k] instanceof Object) {
                        let result = recursiveSearch(obj[k], key, newPath);
                        if (result) {
                            return result;
                        }
                    } else if (Array.isArray(obj[k])) {
                        for (let i = 0; i < obj[k].length; i++) {
                            let result = recursiveSearch(obj[k][i], key, newPath.concat(i));
                            if (result) {
                                return result;
                            }
                        }
                    }
                }
            }
        }
        return null;
    }

    return recursiveSearch(json, entityKey, []);
}

// Example usage:
