Creating a Connect-4 game involves several key components: the game board, the rules of the game, and a way for players to interact with the game. Below is a Python program that implements a simple text-based Connect-4 game for two players.

```python
import numpy as np

ROW_COUNT = 6
COLUMN_COUNT = 7

def create_board():
    board = np.zeros((ROW_COUNT, COLUMN_COUNT))
    return board

def drop_piece(board, row, col, piece):
    board[row][col] = piece

def is_valid_location(board, col):
    return board[ROW_COUNT-1][col] == 0

def get_next_open_row(board, col):
    for r in range(ROW_COUNT):
        if board[r][col] == 0:
            return r

def print_board(board):
    print(np.flip(board, 0))

def winning_move(board, piece):
    # Check horizontal locations for win
    for c in range(COLUMN_COUNT-3):
        for r in range(ROW_COUNT):
            if board[r][c] == piece and board[r][c+1] == piece and board[r][c+2] == piece and board[r][c+3] == piece:
                return True

    # Check vertical locations for win
    for c in range(COLUMN_COUNT):
        for r in range(ROW_COUNT-3):
            if board[r][c] == piece and board[r+1][c] == piece and board[r+2][c] == piece and board[r+3][c] == piece:
                return True

    # Check positively sloped diagonals
    for c in range(COLUMN_COUNT-3):
        for r in range(ROW_COUNT-3):
            if board[r][c] == piece and board[r+1][c+1] == piece and board[r+2][c+2] == piece and board[r+3][c+3] == piece:
                return True

    # Check negatively sloped diagonals
    for c in range(COLUMN_COUNT-3):
        for r in range(3, ROW_COUNT):
            if board[r][c] == piece and board[r-1][c+1] == piece and board[r-2][c+2] == piece and board[r-3][c+3] == piece:
                return True

def main():
    board = create_board()
    print("Welcome to Connect-4!")
    game_over = False
    turn = 0

    while not game_over:
        # Ask for Player 1 Input
        if turn == 0:
            col = int(input("Player 1 Make your Selection (0-6):"))

            if is_valid_location(board, col):
                row = get_next_open_row(board, col)
                drop_piece(board, row, col, 1)

                if winning_move(board, 1):
                    print("Player 1 wins!")
                    print_board(board)
                    game_over = True
                    break
            else:
                print("Invalid move. Try again.")

        # Ask for Player 2 Input
        else:
            col = int(input("Player 2 Make your Selection (0-6):"))

            if is_valid_location(board, col):
                row = get_next_open_row(board, col)
                drop_piece(board, row, col, 2)

                if winning_move(board, 2):
                    print("Player 2 wins!")
                    print_board(board)
                    game_over = True
                    break
            else:
                print("Invalid move. Try again.")

        print_board(board)

        turn += 1
        turn = turn % 2

if __name__ == "__main__":
    main()
```

### Explanation:
1. **Board Creation**: The `create_board` function initializes a 6x7 board using NumPy.
2. **Piece Dropping**: The `drop_piece` function places a piece on the board.
3. **Valid Location Check**: The `is_valid_location` function checks if a column is not full.
4. **Next Open Row**: The `get_next_open_row` function finds the next available row in a column.
5. **Printing the Board**: The `print_board` function prints the board in a flipped orientation for better readability.
6. **Winning Conditions**: The `winning_move` function checks for a winning condition horizontally, vertically, and diagonally.
7. **Game Loop**: The `main` function handles the game loop, alternating turns between the two players and checking for winning conditions.

This program can be run in any Python environment. Players take turns entering the column number where they want to drop their piece. The game continues until one player wins or the board is full.

